## Submitted testbench
```systemverilog
module tb;

  // -----------------------------------------------------------------
  // Parameters
  // -----------------------------------------------------------------
  localparam int CLK_PERIOD      = 8;                     // 125 MHz
  localparam logic [15:0] PRESCALE_VAL = 16'd5;            // same as baseline
  localparam int FRAME_CYCLES = 10 * PRESCALE_VAL * 8;    // 10 bits per frame

  // -----------------------------------------------------------------
  // Clock and reset
  // -----------------------------------------------------------------
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  logic rst = 0;
  initial begin
    rst = 0;
    #200;
    rst = 1;
    #200;
    rst = 0;
    #200;
  end

  // -----------------------------------------------------------------
  // DUT interface signals
  // -----------------------------------------------------------------
  logic        s_axis_tdata;
  logic        s_axis_tvalid;
  logic        s_axis_tready;
  logic [7:0]  m_axis_tdata;
  logic        m_axis_tvalid;
  logic        m_axis_tready;   // forced low to never accept
  logic        rxd;
  logic        txd;
  logic        tx_busy;
  logic        rx_busy;
  logic        rx_overrun_error;
  logic        rx_frame_error;

  // Force m_axis_tready to constant 0 (never accept)
  assign m_axis_tready = 1'b0;

  // Tie unused inputs to known values
  assign s_axis_tdata = 0;
  assign s_axis_tvalid = 0;

  // -----------------------------------------------------------------
  // UART transaction task
  // -----------------------------------------------------------------
  task automatic send_byte(input byte unsigned b);
    int i;
    int bit_clks;
    bit_clks = PRESCALE_VAL * 8;   // clocks per bit

    // Start bit (low)
    rxd = 0;
    #bit_clks;

    // 8 data bits, LSB first
    for (i = 0; i < 8; i = i + 1) begin
      rxd = b[i];
      #bit_clks;
    end

    // Stop bit (high)
    rxd = 1;
    #bit_clks;
  endtask

  // -----------------------------------------------------------------
  // DUT instantiation
  // -----------------------------------------------------------------
  uart #(.DATA_WIDTH(8)) dut (
    .clk          (clk),
    .rst          (rst),
    .s_axis_tdata (s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata (m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),   // input, already held low
    .rxd          (rxd),
    .txd          (txd),
    .tx_busy      (tx_busy),
    .rx_busy      (rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error (rx_frame_error),
    .prescale     (PRESCALE_VAL)
  );

  // -----------------------------------------------------------------
  // Stimulus
  // -----------------------------------------------------------------
  initial begin
    // Allow reset to settle
    #500;

    // First frame (arbitrary payload)
    send_byte(8'hAA);
    #FRAME_CYCLES;

    // Second frame – payload that must appear in m_axis_tdata (0x5A)
    send_byte(8'h5A);
    #FRAME_CYCLES;

    // Third frame – generates the second overrun while the pending
    // data is still 0x5A, satisfying the R17 coverage point.
    send_byte(8'hBB);
    #500;   // give coverage point time to record
    $finish;
  end

endmodule
```

